using System;using System.IO;using System.Text;using System.Linq;using System.Collections.Generic;using System.Web.Script.Serialization;
internal static class SingleNativeReportRegression {
    static readonly JavaScriptSerializer J=new JavaScriptSerializer();static int checks;
    static byte[] Original;const uint Pid=25848,Parent=19708;
    static bool Validate(byte[] bytes,uint pid=Pid,uint parent=Parent,uint exit=0,byte[] stderr=null){try{return LpacSingleNativeBoundary.Validate(bytes,stderr??new byte[0],exit,pid,parent,(n,d)=>{});}catch{return false;}}
    static void Expect(bool condition,string label){if(!condition)throw new Exception("REGRESSION:"+label);checks++;}
    static byte[] Change(int line,string field,object value){var lines=Encoding.UTF8.GetString(Original).TrimEnd('\r','\n').Split('\n');int split=lines[line].IndexOf(':');var d=J.Deserialize<Dictionary<string,object>>(lines[line].Substring(split+1));d[field]=value;lines[line]=lines[line].Substring(0,split+1)+J.Serialize(d);return Encoding.UTF8.GetBytes(String.Join("\n",lines)+"\n");}
    internal static int Main(string[] args){Original=File.ReadAllBytes("docs/archive/2026-11-06-single-process-matrix/attempts/930b420b057d45139863b5e7c6da4718/stdout.bin");Expect(Validate(Original),"actual positive");Expect(!Validate(Original,Pid+1),"wrong primary");Expect(!Validate(Original,Pid,Parent+1),"wrong parent");Expect(!Validate(Original,Pid,Parent,1),"nonzero exit");Expect(!Validate(Original,Pid,Parent,0,new byte[]{1}),"stderr");Expect(!Validate(Encoding.UTF8.GetBytes(Encoding.UTF8.GetString(Original)+"extra\n")),"extra frame");Expect(!Validate(new byte[0]),"missing frames");for(int i=0;i<7;i++)Expect(!Validate(Change(i,"pid",Pid+1)),"wrong bound report pid"+i);
    foreach(var change in new object[][]{new object[]{0,"override_create_error",0},new object[]{0,"override_attribute_error",5},new object[]{0,"parent_privileged_open_errors",new[]{5,0,5}},new object[]{0,"parent_privileged_access",new[]{128,41,64}},new object[]{1,"child_policy_flags",0},new object[]{1,"baseline_create_error",0},new object[]{1,"breakaway_create_error",87},new object[]{1,"console_allocated",true},new object[]{1,"console_error",87},new object[]{2,"read_hresult",5},new object[]{2,"absent_value_query",0},new object[]{2,"write_hresult",0},new object[]{2,"write_dac_hresult",0},new object[]{3,"rows",new object[0]},new object[]{4,"role",1},new object[]{4,"rows",new object[0]},new object[]{5,"system_read_error",5},new object[]{5,"host_fake_read_error",0},new object[]{5,"host_fake_write_error",87},new object[]{6,"connected",true},new object[]{6,"hresult",0},new object[]{6,"creation_method_reached",true}})Expect(!Validate(Change((int)change[0],(string)change[1],change[2])),"mutant "+change[0]+":"+change[1]);
    Console.WriteLine("SINGLE_NATIVE_REPORT_REGRESSION checks="+checks+" inner_exit_code=0");return 0;}
}
